// Renderer-independent connection commands. Native files expose six network
// families; endpoint/port compatibility remains definition-driven and is
// deliberately not guessed here.
import { assertGridVector } from './grid.js';

export const LINK_KINDS = ['electric', 'mechanical', 'liquid', 'gas', 'belt', 'data'];

// These diagnostic colours identify a network family consistently in the
// connection toolbar, endpoint markers, and rendered links.
export const LINK_COLORS = Object.freeze({
  electric: '#f1c232',
  mechanical: '#f2994a',
  liquid: '#2f80ed',
  gas: '#27ae60',
  belt: '#98a2b3',
  data: '#9b51e0',
});

// Routed connections use faceted octagonal tubes; belts are a direct dashed
// node-to-node indicator. Keep committed routes and previews in agreement.
export const LINK_RENDER_STYLES = Object.freeze({
  electric: { radius: .009, radialSegments: 8 },
  mechanical: { radius: .022, radialSegments: 8 },
  liquid: { radius: .021, radialSegments: 8 },
  gas: { radius: .019, radialSegments: 8 },
  belt: { linewidth: 3, dashSize: .04, gapSize: .025 },
  data: { radius: .0075, radialSegments: 8 },
});

const clone = value => structuredClone(value);
const port = value => value === undefined ? 0 : value;
const nativeProjectedPoint = point => point && ['x', 'y', 'z'].every(axis => typeof point[axis] === 'number' && Number.isFinite(point[axis]) && Math.abs(point[axis]) <= 10000);
const routePoint = (point, nativeProjected) => {
  if (!nativeProjected) return assertGridVector(point, 'Connection route point');
  if (!nativeProjectedPoint(point)) throw new Error('Native connection route point is invalid');
  return clone(point);
};

function endpoint(value, label, componentIds) {
  if (!value || typeof value.componentId !== 'string' || !value.componentId) throw new Error(`${label} endpoint must reference a component`);
  if (componentIds && !componentIds.has(value.componentId)) throw new Error(`${label} endpoint references an unknown component: ${value.componentId}`);
  if (!Number.isInteger(port(value.port)) || port(value.port) < 0 || port(value.port) > 255) throw new Error(`${label} port must be an integer from 0 to 255`);
  return { componentId: value.componentId, ...(value.port === undefined ? {} : { port: value.port }) };
}

export function validateLinks(links = [], componentIds = null) {
  if (!Array.isArray(links)) throw new Error('Connections must be an array');
  const ids = new Set();
  return links.map((link, index) => {
    if (!link || typeof link.id !== 'string' || !link.id || ids.has(link.id)) throw new Error(`Connection ID is invalid or duplicated: ${index}`);
    if (!LINK_KINDS.includes(link.kind)) throw new Error(`Unsupported connection kind: ${String(link.kind)}`);
    const from = endpoint(link.from, 'Connection source', componentIds);
    const to = endpoint(link.to, 'Connection target', componentIds);
    if (from.componentId === to.componentId && port(from.port) === port(to.port)) throw new Error('A connection cannot use the same component port twice');
    if (!Array.isArray(link.points) || link.points.length > 256) throw new Error('Connection route must contain at most 256 points');
    if (link.color !== undefined && (!Number.isInteger(link.color) || link.color < 0 || link.color > 255)) throw new Error('Connection color must be an integer from 0 to 255');
    if (link.paintColor !== undefined && (typeof link.paintColor !== 'string' || !/^#[\da-f]{6}$/i.test(link.paintColor))) throw new Error('Connection paint color must be a Hex RGB value');
    if (link.nativeProjected !== undefined && link.nativeProjected !== true) throw new Error('Native connection projection is invalid');
    ids.add(link.id);
    const normalized = {
      id: link.id, kind: link.kind, from, to,
      points: link.points.map(point => routePoint(point, link.nativeProjected === true)),
      ...(link.nativeProjected ? { nativeProjected: true } : {}),
    };
    if (Number.isInteger(link.color) && link.color >= 0 && link.color <= 255) normalized.color = link.color;
    if (typeof link.paintColor === 'string') normalized.paintColor = link.paintColor.toLowerCase();
    return normalized;
  });
}

export function createLink(links, value, componentIds = null) {
  const next = validateLinks(links, componentIds);
  const prefix = `${value.kind}-link`;
  let index = 1;
  while (next.some(link => link.id === `${prefix}-${index}`)) index++;
  const [link] = validateLinks([{ ...clone(value), id: `${prefix}-${index}` }], componentIds);
  return { links: [...next, link], link };
}

export function removeLink(links, id, componentIds = null) {
  const next = validateLinks(links, componentIds);
  if (!next.some(link => link.id === id)) throw new Error(`Connection does not exist: ${id}`);
  return { links: next.filter(link => link.id !== id) };
}

// Route points are independent editor data: moving one must not mutate the
// imported link or any sibling route point. Native projected routes retain the
// fractional coordinates observed in the source file; authored routes remain
// aligned to the editor's integer-cell grid.
export function moveLinkPoint(links, id, pointIndex, position, componentIds = null) {
  const next = validateLinks(links, componentIds);
  if (!Number.isInteger(pointIndex) || pointIndex < 0) throw new Error('Connection route point index is invalid');
  const linkIndex = next.findIndex(link => link.id === id);
  if (linkIndex < 0) throw new Error(`Connection does not exist: ${id}`);
  const link = next[linkIndex];
  if (pointIndex >= link.points.length) throw new Error('Connection route point does not exist');
  const points = link.points.map((point, index) => index === pointIndex ? routePoint(position, link.nativeProjected === true) : clone(point));
  const linksWithMove = next.map((value, index) => index === linkIndex ? { ...value, points } : value);
  const validated = validateLinks(linksWithMove, componentIds);
  return { links: validated, link: validated[linkIndex] };
}
