// Anymaker mesh v5: structurally verified on local ROM files, not an engine shader emulator.
// Pure ArrayBuffer parser shared by browser, Node audit and synthetic-fixture tests.
const LAYOUTS = new Map([
  ['3,1,5,2,2,3,3,4', { stride: 36, uv: 16, normal: 24 }],
  ['3,1,5,2,3,4,0,0', { stride: 28, normal: 16 }],
  ['3,1,5,2,0,0,0,0', { stride: 16 }],
]);

export function parseMesh(input) {
  const bytes = input instanceof ArrayBuffer ? new Uint8Array(input)
    : new Uint8Array(input.buffer, input.byteOffset, input.byteLength);
  if (bytes.length > 64 * 1024 * 1024) throw new Error('Mesh exceeds 64 MiB limit');
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  let offset = 0;
  const need = (n) => { if (!Number.isSafeInteger(n) || n < 0 || offset + n > bytes.length) throw new Error(`Truncated mesh at ${offset}, need ${n} bytes`); };
  const u32 = () => { need(4); const v = view.getUint32(offset, true); offset += 4; return v; };
  const text = (n) => { need(n); const s = new TextDecoder().decode(bytes.subarray(offset, offset + n)); offset += n; return s.replace(/�$/, ''); };
  const finite = (v) => { if (!Number.isFinite(v) || Math.abs(v) > 1e9) throw new Error(`Invalid float at ${offset}`); return v; };
  if (text(4) !== 'mesh') throw new Error('Not an Anymaker mesh');
  const version = u32();
  if (version !== 5) throw new Error(`Unsupported mesh version ${version}`);
  const count = u32();
  if (!count || count > 256) throw new Error('Invalid submesh count');
  const parts = [];
  for (let part = 0; part < count; part++) {
    const length = u32();
    if (length > 4096) throw new Error('Invalid mesh name length');
    const name = text(length);
    const header = offset;
    need(140);
    const signature = Array.from({ length: 8 }, () => u32());
    const layout = LAYOUTS.get(signature.join(','));
    if (!layout) throw new Error(`Unsupported vertex layout: ${signature}`);
    // Opaque 56 bytes retained for subsequent material/texture reverse engineering.
    const metadata = Array.from(bytes.subarray(header + 32, header + 88));
    offset = header + 88;
    const bounds = Array.from({ length: 6 }, () => { const v = finite(view.getFloat64(offset, true)); offset += 8; return v; });
    const vertexBytes = u32();
    if (!vertexBytes || vertexBytes % layout.stride) throw new Error('Invalid vertex buffer size');
    need(vertexBytes);
    const n = vertexBytes / layout.stride;
    if (n > 1_000_000) throw new Error('Too many vertices');
    const positions = new Float32Array(n * 3);
    const colors = new Uint8Array(n * 4);
    const normals = layout.normal ? new Float32Array(n * 3) : null;
    const uv = layout.uv ? new Float32Array(n * 2) : null;
    for (let i = 0; i < n; i++) {
      const at = offset + i * layout.stride;
      for (let a = 0; a < 3; a++) {
        positions[i * 3 + a] = finite(view.getFloat32(at + a * 4, true));
        if (normals) normals[i * 3 + a] = finite(view.getFloat32(at + layout.normal + a * 4, true));
      }
      colors.set(bytes.subarray(at + 12, at + 16), i * 4);
      if (uv) for (let a = 0; a < 2; a++) uv[i * 2 + a] = finite(view.getFloat32(at + layout.uv + a * 4, true));
    }
    offset += vertexBytes;
    const indexBytes = u32();
    if (!indexBytes || indexBytes % 12) throw new Error('Index buffer is not a triangle list');
    need(indexBytes);
    const indices = new Uint32Array(indexBytes / 4);
    for (let i = 0; i < indices.length; i++) { indices[i] = u32(); if (indices[i] >= n) throw new Error('Index outside vertex buffer'); }
    parts.push({ name, signature, metadata, bounds, positions, normals, colors, uv, indices });
  }
  // Rigged/extended trailers must not be silently interpreted as static geometry.
  if (bytes.length - offset !== 8 || u32() !== 0 || u32() !== 0) throw new Error('Unsupported mesh trailer (possibly skeleton/animation)');
  return { version, parts };
}
